<?= $this->extend(ADMIN_VIEW.'layout') ?><?= $this->section('styles') ?><style>.shopify-callbacks .card{border:1px solid #e3e8ef;border-radius:14px;overflow:hidden}.shopify-callbacks .table{min-width:980px}.shopify-callbacks .table th{background:#f8fafc;color:#64748b;font-size:.72rem;letter-spacing:.05em;text-transform:uppercase;white-space:nowrap}.shopify-callbacks .table td,.shopify-callbacks .table th{padding:.9rem 1rem;vertical-align:middle}.shopify-callbacks .callback-note{display:block;max-width:220px;max-height:72px;overflow:auto;font-size:.82rem;white-space:pre-wrap;word-break:break-word}.shopify-callbacks .callback-action{white-space:nowrap}</style><?= $this->endSection() ?><?= $this->section('main-content') ?><main class="dashboard-container shopify-callbacks"><div class="page-heading d-flex justify-content-between align-items-start flex-wrap"><div><div class="page-eyebrow">Shopify / AI Analysis</div><h1 class="h3 mb-1">Callback requests</h1><p class="text-muted mb-0">High-priority requests linked to their AI analysis and CRM follow-up.</p></div><div class="mt-2 mt-md-0"><a class="btn btn-outline-primary mr-2" href="<?= base_url('admin/integrations/shopify/ai-hair-analysis/leads') ?>">Analysis leads</a><a class="btn btn-dark" href="<?= base_url('admin/crm/follow-ups') ?>">All follow-ups</a></div></div><?php if(!empty($migrationRequired)): ?><div class="alert alert-warning">Run <code>php spark migrate</code> before viewing callback requests.</div><?php endif; ?><section class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Priority</th><th>Analysis</th><th>Customer</th><th>Preferred time</th><th>Note</th><th>Status</th><th>Received</th><th>Action</th></tr></thead><tbody><?php foreach($requests as $request): $followUpId=(int)($request['follow_up_id']??0); ?><tr class="<?= $request['priority']==='high'?'table-warning':'' ?>"><td><span class="badge badge-danger">HIGH</span></td><td><strong><?= esc(strtoupper((string)$request['analysis_type'])) ?></strong><br><code><?= esc($request['lead_reference']) ?></code></td><td><?= esc($request['shopify_customer_id']) ?><br><small><?= esc($request['store_domain']) ?></small></td><td><?= esc((string)($request['preferred_time']??'—')) ?></td><td><span class="callback-note"><?= esc((string)($request['note']??'—')) ?></span></td><td><?= esc(ucwords(str_replace('_',' ',(string)$request['status']))) ?></td><td><?= esc((string)($request['created_at']??'—')) ?></td><td class="callback-action"><?php if($followUpId>0): ?><a class="btn btn-sm btn-primary" href="<?= base_url('admin/crm/follow-ups/'.$followUpId) ?>"><i class="bi bi-arrow-up-right mr-1"></i>Open follow-up</a><?php else: ?><span class="badge badge-light">Not linked</span><?php endif; ?></td></tr><?php endforeach; ?><?php if($requests===[]): ?><tr><td colspan="8" class="text-center text-muted py-4">No callback requests.</td></tr><?php endif; ?></tbody></table></div></section></main><?= $this->endSection() ?>
